mapper.select:
SELECT  FROM knowledge_submission
WHERE author_user_id = #{authorUserId}
ORDER BY updated_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE 1 = 1
AND status = #{status}
AND risk_level = #{riskLevel}
AND source_type = #{sourceType}

mapper.select:
SELECT  FROM knowledge_submission

ORDER BY CASE risk_level WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END, created_at
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE knowledge_submission_version
SET cleaned_content = #{cleanedContent}, content_checksum = #{contentChecksum}, ai_summary = #{summary},
    risk_level = #{riskLevel}, risk_labels = #{riskLabels}, quality_score = #{qualityScore}
WHERE submission_id = #{submissionId} AND version = #{version}

UPDATE knowledge_submission SET status = 'PUBLISHING', reviewer_user_id = #{reviewerUserId},
    reviewed_at = #{reviewedAt}, updated_at = #{reviewedAt}
WHERE id = #{id} AND current_version = #{expectedVersion} AND status = 'PENDING_REVIEW'

UPDATE knowledge_submission SET status = 'REJECTED', reviewer_user_id = #{reviewerUserId},
    reviewed_at = #{reviewedAt}, error_message = #{reason}, updated_at = #{reviewedAt}
WHERE id = #{id} AND current_version = #{expectedVersion} AND status = 'PENDING_REVIEW'

UPDATE knowledge_submission SET status = 'PUBLISHED', published_document_id = #{documentId},
    published_at = #{publishedAt}, error_message = NULL, updated_at = #{publishedAt}
WHERE id = #{id} AND current_version = #{expectedVersion} AND status = 'PUBLISHING'

UPDATE knowledge_submission SET status = 'FAILED', error_message = #{errorMessage}, updated_at = #{updatedAt}
WHERE id = #{id} AND current_version = #{expectedVersion}
  AND status IN ('PRECHECKING', 'PUBLISHING')

UPDATE knowledge_submission SET status = 'WITHDRAWN', consent_status = 'WITHDRAWN', updated_at = #{updatedAt}
WHERE id = #{id} AND author_user_id = #{authorUserId}
  AND status IN ('PRECHECKING', 'PENDING_REVIEW', 'REJECTED', 'PUBLISHED', 'FAILED')
